class HookStateMachine {
  private currentState: State;
  private states: Map<string, State>;

  constructor() {
    this.states = new Map();
    this.addState('idle', new IdleState());
    this.addState('swinging', new SwingingState());
    this.addState('launching', new LaunchingState());
    this.addState('reeling', new ReelingState());
    this.addState('grabbing', new GrabbingState());

    this.currentState = this.states.get('idle')!;
    this.currentState.onEnter();
  }

  addState(name: string, state: State) {
    this.states.set(name, state);
  }

  changeState(newStateName: string) {
    if (this.states.has(newStateName)) {
      this.currentState.onExit();
      this.currentState = this.states.get(newStateName)!;
      this.currentState.onEnter();
    }
  }

  update() {
    this.currentState.update(this);
  }
}

class State {
  onEnter() {}
  onExit() {}
  update(machine: HookStateMachine) {}
}

class IdleState extends State {
  onEnter() {
    console.log('Hook is idle');
  }

  update(machine: HookStateMachine) {
    // Wait for launch input
    if (someLaunchCondition()) {
      machine.changeState('launching');
    }
  }
}

class SwingingState extends State {
  private swingTimer: number = 0;

  onEnter() {
    console.log('Hook is swinging');
  }

  update(machine: HookStateMachine) {
    this.swingTimer++;
    // Swing animation logic
    if (this.swingTimer > SWING_DURATION && someLaunchCondition()) {
      machine.changeState('launching');
    }
    if (this.swingTimer > MAX_SWING_TIME) {
      machine.changeState('idle');
    }
  }
}

class LaunchingState extends State {
  onEnter() {
    console.log('Hook is launching');
  }

  update(machine: HookStateMachine) {
    // Launch logic - move hook down
    if (hookReachedBottom()) {
      machine.changeState('reeling');
    }
    if (hookHitItem()) {
      machine.changeState('grabbing');
    }
  }
}

class ReelingState extends State {
  onEnter() {
    console.log('Hook is reeling up');
  }

  update(machine: HookStateMachine) {
    // Reel up logic
    if (hookReachedTop()) {
      machine.changeState('idle');
    }
  }
}

class GrabbingState extends State {
  onEnter() {
    console.log('Hook is grabbing item');
  }

  update(machine: HookStateMachine) {
    // Grabbing logic
    if (itemSecured()) {
      machine.changeState('reeling');
    }
  }
}

