// 定义Item接口
interface Item {
  x: number;
  y: number;
  value: number;
}

// 定义状态枚举
enum HookState {
  Idle = 'idle',
  Swinging = 'swinging',
  Launching = 'launching',
  Reeling = 'reeling',
  Grabbing = 'grabbing'
}

class Hook {
  x: number = 0;
  y: number = 0;
  state: HookState = HookState.Idle;
  targetX: number = 0;
  targetY: number = 0;
  speed: number = 5;

  update() {
    switch (this.state) {
      case HookState.Swinging:
        this.x += Math.sin(Date.now() / 1000) * 5;
        break;
      case HookState.Reeling:
        // 简化的回收逻辑
        if (this.y > 0) {
          this.y -= this.speed;
        } else {
          this.state = HookState.Idle;
        }
        break;
      case HookState.Launching:
        // 发射逻辑
        if (this.y < this.targetY) {
          this.y += this.speed;
        } else {
          this.state = HookState.Reeling;
        }
        break;
      // 其他状态的处理
    }
  }

  catchItem(item: Item) {
    if (this.state === HookState.Launching || this.state === HookState.Grabbing) {
      this.state = HookState.Reeling;
      // 可能还需要处理物品抓取逻辑
    }
  }

  launch(targetX: number, targetY: number) {
    if (this.state === HookState.Idle) {
      this.state = HookState.Launching;
      this.targetX = targetX;
      this.targetY = targetY;
    }
  }
}
